<?php require dirname(__DIR__).'/config/config.php'; require dirname(__DIR__).'/vendor/autoload.php'; use App\Helpers\Security; use App\Helpers\Audit; Security::requireRole(['administrador']);$msg=null;if($_SERVER['REQUEST_METHOD']==='POST'){Security::checkCsrf($_POST['csrf']??null);$senha=$_POST['senha']??'';if(strlen($senha)<8){$msg='A senha deve ter pelo menos 8 caracteres.';}else{$s=db()->prepare('INSERT INTO usuarios(nome,email,senha,nivel,status) VALUES(?,?,?,?,?)');$s->execute([trim($_POST['nome']),filter_var($_POST['email'],FILTER_VALIDATE_EMAIL),password_hash($senha,PASSWORD_DEFAULT),$_POST['nivel'],1]);Audit::log('Cadastro de usuário','usuarios',(int)db()->lastInsertId());$msg='Usuário criado.';}}$rows=db()->query('SELECT id,nome,email,nivel,status,created_at FROM usuarios ORDER BY id DESC')->fetchAll();?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Usuários</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container py-4"><h1>Usuários</h1><a href="dashboard.php">← Dashboard</a><?php if($msg):?><div class="alert alert-info mt-3"><?=Security::e($msg)?></div><?php endif;?><div class="card p-3 my-4"><form method="post" class="row g-2"><input type="hidden" name="csrf" value="<?=Security::csrf()?>"><div class="col-md-3"><input class="form-control" name="nome" placeholder="Nome" required></div><div class="col-md-3"><input class="form-control" type="email" name="email" placeholder="E-mail" required></div><div class="col-md-2"><input class="form-control" type="password" name="senha" placeholder="Senha" required></div><div class="col-md-2"><select class="form-select" name="nivel"><option>administrador</option><option>gerente</option><option>operador</option><option>cliente</option></select></div><div class="col-md-2"><button class="btn btn-primary">Criar</button></div></form></div><table class="table"><thead><tr><th>Nome</th><th>E-mail</th><th>Nível</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=Security::e($r['nome'])?></td><td><?=Security::e($r['email'])?></td><td><?=Security::e($r['nivel'])?></td><td><?=$r['status']?'Ativo':'Inativo'?></td></tr><?php endforeach;?></tbody></table></div></body></html>
